#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <queue>
using namespace std;

const int MAXN=202;
const int INF=0x3f3f3f3f;

int flow[MAXN][MAXN], cap[MAXN][MAXN], pre[MAXN], dist[MAXN];
int gridA[11][11], gridB[11][11], n, t, bi, bj;
int matrix[101][101];
vector<int> ca, cb, cc;
int directions[4][2]={{0,1},{0,-1},{1,0},{-1,0}};

int compute_max_flow(int n, int s, int e) {
    int total=0;
    while (true) {
        memset(pre, -1, sizeof(pre));
        dist[s]=INF;
        int front=0, rear=0;
        queue<int> q;
        q.push(s);
        while (!q.empty() && pre[e]<0) {
            int u=q.front(); q.pop();
            for (int v=0; v<n; v++) {
                if (pre[v]<0 && cap[u][v]-flow[u][v]>0) {
                    pre[v]=u;
                    dist[v]=min(dist[u], cap[u][v]-flow[u][v]);
                    q.push(v);
                }
            }
        }
        if (pre[e]<0) break;
        for (int v=e; v!=s; v=pre[v]) {
            flow[pre[v]][v]+=dist[e];
            flow[v][pre[v]]-=dist[e];
        }
        total+=dist[e];
    }
    return total;
}

void traverse(int A, int B, int* visited, bool check) {
    queue<pair<int,int>> q;
    visited[A*n+B]=0;
    q.push({A,B});
    while (!q.empty()) {
        auto p=q.front(); q.pop();
        int pIdx=p.first*n+p.second;
        int dis=visited[pIdx];
        if (check && (matrix[bi*n+bj][pIdx]<=dis || t<=dis)) {
            if (matrix[bi*n+bj][pIdx]<dis || t<dis) visited[pIdx]=INF+1;
            continue;
        }
        for (int d=0; d<4; d++) {
            int ni=p.first+directions[d][0];
            int nj=p.second+directions[d][1];
            if (ni<0 || nj<0 || ni>=n || nj>=n) continue;
            if (gridB[ni][nj]<'0' || gridB[ni][nj]>'9') continue;
            int qIdx=ni*n+nj;
            if (visited[qIdx]!=INF) continue;
            visited[qIdx]=dis+1;
            q.push({ni,nj});
        }
    }
}

int main() {
    cin>>n>>t;
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) cin>>gridA[i][j];
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) cin>>gridB[i][j];
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]=='Z') bi=i, bj=j;
        }
    }
    memset(matrix, 0x3f, sizeof(matrix));
    traverse(bi, bj, matrix[bi*n+bj], false);
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]>='1' && gridA[i][j]<='9') {
                traverse(i, j, matrix[i*n+j], true);
            }
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]>='0' && gridA[i][j]<='9') {
                int p=i*n+j;
                cap[p+2+ n*n][1]=gridA[i][j]-'0';
            }
        }
    }
    int z=bi*n+bj;
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridB[i][j]>='0' && gridB[i][j]<='9') {
                int p=i*n+j;
                cap[0][p+2]=gridB[i][j]-'0';
                for (int k=0; k<(int)ca.size(); k++) {
                    int ii=ca[k], jj=cb[k], qIdx=ii*n+jj;
                    if (matrix[p][qIdx]<INF)
                        cap[p+2][qIdx+2+ n*n]=INF;
                }
            }
        }
    }
    cout<<compute_max_flow(2+n*n, 0, 1)<<endl;
}
